  'vec.intro': "임베딩 열 vector(n)(n: 벡터 공급자의 차원 수), 거리용 HNSW 인덱스, 그리고 소스 열이 바뀌면 행을 다시 임베딩하는 트리거를 추가합니다. 그러면 검색 유형 vector 또는 hybrid의 검색 구성이나 AI 에이전트의 Retrieve 도구가 의미로 행을 찾습니다. 지금 있는 행은 바로 임베딩 대기열에 들어갑니다.",
  'vec.existing': "현재 벡터 열",
  'vec.provider': "벡터 공급자",
  'vec.provider_help': "이 작업 영역 애플리케이션의 공유 구성 요소 › 벡터 공급자. 검색할 때도 같은 공급자를 사용하십시오.",
  'vec.keep': "최신 상태 유지",
  'vec.keep_help': "함수 공급자는 트리거에서 바로 임베딩을 설정할 수 있습니다. AI 서비스는 서버가 호출합니다: 트리거가 행을 대기열에 넣고, 서버가 공급자의 분당 요청 수와 애플리케이션의 일일 AI 한도 안에서 대기열의 행을 일괄로 임베딩합니다.",
  'vec.mode_set': "트리거가 바로 설정",
  'vec.mode_queue': "서버용 대기열에 넣음",
  'vec.sources': "소스 열",
  'vec.sources_help': "임베딩할 텍스트: 이 열들, 한 줄에 하나씩. 그중 하나가 바뀌면 행을 다시 임베딩합니다.",
  'vec.distance': "거리",
  'vec.distance_help': "대부분의 임베딩 모델에는 cosine; 검색 구성도 같은 거리를 사용합니다.",
  'vec.column': "벡터 열",
  'vec.no_key': "테이블에 열 하나로 된 기본 키가 필요합니다: 대기열은 그것으로 행을 찾습니다.",
  'vec.pick_provider': "벡터 공급자를 선택하십시오.",
  'vec.no_providers': "이 작업 영역의 애플리케이션에는 아직 벡터 공급자가 없습니다: 공유 구성 요소 › 벡터 공급자에서 추가하십시오.",
  'vec.missing': "이 데이터베이스에 pgvector 확장이 설치되어 있지 않아 아직 벡터 열을 추가할 수 없습니다.",
  'vec.missing_create': "데이터베이스 서버에 pgvector {version}이(가) 있습니다: 작업 영역 유틸리티 › 벡터 공급자에서 확장을 만드십시오.",
  'vec.missing_admin': "데이터베이스 서버에 pgvector {version}이(가) 있습니다: 관리자가 확장을 만듭니다(작업 영역 유틸리티 › 벡터 공급자).",
  'vec.missing_package': "데이터베이스 서버에 pgvector 패키지가 없습니다: 설치한 다음(예: apt install postgresql-17-pgvector 또는 Docker 이미지 pgvector/pgvector) 확장을 만드십시오.",
  'vec.utilities': "작업 영역 유틸리티 › 벡터 공급자",
  'vec.kept_by': "{provider}이(가) {columns}에서 유지",
