  'st.header_title': 'HTTP 헤더 인증',
  'st.header_intro': '인증이 "HTTP 헤더"일 때만 사용됩니다. 역방향 프록시나 Single Sign-On 게이트웨이가 사용자를 로그인시키고 헤더로 사용자 이름을 전달합니다. pgkiln은 {env}에 지정된 프록시 주소에서 온 경우에만 이를 신뢰합니다',
