  'st.header_auto': '계정 자동 생성',
  'st.header_auto_help': '알 수 없는 사용자 이름에는 이 앱에 대한 액세스 권한이 있는 새 계정이 생성됩니다. 그렇지 않으면 계정이 존재하고 액세스 권한이 있어야 합니다.',
  'st.db_title': '데이터베이스 계정',
  'st.db_intro': '인증이 "데이터베이스 계정"일 때만 사용됩니다. 사용자는 PostgreSQL 로그인 역할과 그 비밀번호로 로그인하며, 해당 역할로 이 데이터베이스에 잠시 연결하여 확인합니다. 슈퍼유저와 pgkiln 자체 역할은 항상 거부되며, 두 필드가 모두 비어 있으면 아무도 로그인할 수 없습니다.',
  'st.db_roles': '허용된 역할',
