  'st.db_member': '또는 다음 역할의 구성원',
  'st.db_member_ph': '예: app_users_group',
  'st.db_member_help': '이 역할의 모든 구성원도 로그인할 수 있습니다.',
  'st.custom_title': '사용자 정의 인증',
  'st.custom_intro': '인증이 "사용자 정의"일 때만 사용됩니다. 직접 작성한 PL/pgSQL이 애플리케이션의 데이터베이스 역할로 로그인 폼의 사용자 이름과 비밀번호를 확인합니다. 비밀번호는 매개변수로 전달되며 기록되지 않습니다. 실패한 시도는 다른 로그인과 마찬가지로 제한됩니다. 두 필드가 모두 비어 있으면 아무도 로그인할 수 없습니다.',
  'st.custom_fn': '함수 이름',
  'st.custom_fn_ph': '예: app.check_login',
  'st.custom_fn_help': 'boolean을 반환하는 함수(p_username text, p_password text)로, 소문자이며 선택적으로 스키마를 붙입니다. 앱의 역할에 EXECUTE 권한이 필요합니다. 아래 본문보다 우선합니다.',
  'st.custom_body': '또는 함수 본문',
  'st.custom_body_help': 'p_username과 p_password를 사용하고 올바른 로그인이면 true를 반환하는 PL/pgSQL. 예: {example}',
