  'wsp.iso_help': '격리하면 작업공간이 자체 데이터베이스 로그인 두 개와 현재 애플리케이션이 사용하는 데이터베이스 역할을 갖게 됩니다. 그러면 애플리케이션 코드는 해당 역할과 이 작업공간의 애플리케이션에만 접근하며, 개발자의 SQL Workshop은 소유자 대신 작업공간의 로그인으로 실행됩니다. 새 애플리케이션은 자체 역할과 스키마를 새로 받습니다.',
