  'wsp.sql_on_help': '꺼짐: 이 작업공간이 현재 작업공간인 동안 모든 개발자에 대해 SQL 워크시트, 객체 브라우저, SQL 스크립트, 데이터 로드 및 언로드, Quick SQL, 쿼리 빌더, DDL, 비교 및 AI가 거부됩니다.',
