  'wsp.description': '설명',
  'wsp.add_link': '링크 추가',
  'wsp.switched': '작업공간 {name}.',
  'wsp.intro': '작업공간은 애플리케이션과 이를 구축하는 개발자를 묶습니다. 개발자는 자신의 작업공간에 있는 애플리케이션을 보고 변경할 수 있으며, 관리자는 모두 볼 수 있습니다. 공유 작업공간은 SQL을 작성하는 개발자 사이의 보안 경계가 아닙니다. SQL Workshop과 애플리케이션 코드는 이 설치의 권한으로 실행됩니다. {isolated} 작업공간은 보안 경계입니다. 애플리케이션과 SQL이 자체 데이터베이스 역할과 자체 애플리케이션에만 접근하는 자체 데이터베이스 로그인으로 실행됩니다.',
