  'rs.saving_needs_a_process_of': '저장하려면 이 영역에 "grid_dml" 유형의 프로세스가 필요합니다. 없으면 그리드는 읽기 전용입니다.',
  'rs.column_sum_avg_count_min': '열=sum, avg, count, min 또는 max이며 열은 ";"로 구분합니다. 페이지만이 아니라 검색의 모든 행으로 계산됩니다. 사용자가 직접 추가할 수 있습니다(작업 → 집계).',
  'rs.stay_in_view_while_the': '그리드를 가로로 스크롤해도 보이도록 유지됩니다. 사용자가 변경할 수 있고 열을 이동, 크기 조정, 숨길 수 있으며, JSON의 "layout"이 기본 순서와 너비를 정합니다.',
  'rs.views_users_may_switch_to': '그리드 외에 사용자가 전환할 수 있는 보기입니다. 단일 행 보기는 한 번에 한 행을 편집하며(행 작업 메뉴에서도 가능), 그룹화와 차트는 작업에서 설정합니다.',
  'rs.a_master_grid_s_selected': '마스터 그리드에서 선택한 행이 값을 페이지 항목에 넣고, 디테일 그리드와 보고서는 쿼리(:P1_ID)에서 이를 사용해 페이지를 다시 로드하지 않고 새로 고쳐집니다. 다른 영역 유형은 {"master": {"item": "P1_ID"}}로 따릅니다.',
  'rs.edit_as_picks_a_shared': '"편집 방식"은 선택 목록에 사용할 공유 값 목록(공유 구성 요소 → 값 목록)을 고릅니다.',
  'rs.col_validations': '열 검증',
  'rs.col_validations_summary': '새 행이나 변경된 행이 충족해야 하는 열별 SQL 표현식',
  'rs.valid_when': '유효 조건(SQL 표현식)',
  'rs.error_message': '오류 메시지',
  'rs.aria_valid_when': '{name}의 유효 조건',
  'rs.aria_error_message': '{name}의 오류 메시지',
  'rs.col_validations_help': '추가되거나 변경되는 행에 대해 표현식이 참이어야 합니다. 행의 열은 대문자 이름의 바인드 변수입니다(:SAL, :COMM). 페이지 항목과 :APP_USER도 사용할 수 있습니다. 조건을 충족하지 않는 행은 저장되지 않고 메시지가 해당 셀에 표시됩니다.',
  'rs.the_visible_area_and_vector': '보이는 영역과 벡터 타일에는 `lat`/`lng`(또는 PostGIS 지오메트리)가 필요하며 지도를 움직이면 다시 로드됩니다. 벡터 타일은 점, 선, 영역을 그리며 클러스터링이나 목록은 없습니다.',
  'rs.the_same_columns_as_the': '지도 자체 쿼리와 같은 열입니다. 레이어를 제거하려면 쿼리를 비우십시오.',
  'rs.the_condition_runs_on_the': '조건은 서버에서 실행됩니다. PostGIS가 설치되어 있으면 geometry/geography 열로, 아니면 위도와 경도로 판단합니다.',
  'rs.users_switch_between_the_ticked': '사용자는 선택한 보기 사이를 전환합니다. 이벤트에 필요하면 범위 밖의 시간도 추가됩니다.',
  'rs.runs_as_the_application_s': '애플리케이션의 데이터베이스 롤로 실행되며(행 수준 보안 적용) `:EVENT_ID`(키 열의 값), `:NEW_START`, `:NEW_END`(이전과 같은 기간)를 사용합니다. 비어 있으면 이벤트를 끌 수 없습니다.',
  'rs.only_events_the_user_sees': '이 캘린더에서 사용자가 보는 이벤트만 옮길 수 있으며, 마우스가 없으면 편집 링크로 날짜를 바꿉니다.',
  'rs.not_while_the_pointer_or': '포인터나 포커스가 캐러셀에 있는 동안, 그리고 동작 줄이기를 선호하는 사용자에게는 넘어가지 않습니다. 캐러셀에는 "모두 표시"가 없습니다.',
  'rs.a_chosen_region_gets_display': '선택한 영역의 설정에 `"display_selector": true`(영역 이름의 탭) 또는 탭 이름이 들어갑니다. 탭 이름이 같은 영역은 한 탭을 공유합니다(예: 스마트 필터와 해당 보고서). JavaScript가 없으면 모든 영역이 각 영역으로의 링크와 함께 표시됩니다.',
  'rs.gauge_charts_only_a_warning': '게이지 차트에만 적용됩니다. 경고 임계값이 위험 임계값보다 높으면 낮은 값이 나쁜 것입니다(예: 경고 50, 위험 20).',
  'rs.drill_down_column_takes_the': '드릴다운: `#column#`은 점의 행 값을, `#series#`는 해당 계열 이름을 가져옵니다. 링크만 참조하는 열은 그리지 않습니다.',
  'rs.gantt_charts_with_a_task': '`task_id` 열이 있는 간트 차트입니다. 애플리케이션의 데이터베이스 롤로 실행되며(행 수준 보안 적용) `:TASK_ID`, `:NEW_START`, `:NEW_END`(`YYYY-MM-DD`, 시간 단위면 `YYYY-MM-DDTHH:MM`, 마일스톤은 시작과 끝이 같음)를 사용합니다. 비어 있으면 작업을 끌 수 없습니다.',
  'rs.only_tasks_the_user_sees': '이 차트에서 사용자가 보는 작업만 옮길 수 있으며, 이후 차트는 쿼리에서 다시 그려집니다.',
