  // ------------------------------------------------------------ Region settings help (CD-8)
  'rs.not_in_query': '쿼리에 없음',
  'rpt.report_settings': '보고서 설정',
  'rpt.save_report_settings': '보고서 설정 저장',
  'rs.no_position_alert': '보고서에 `lat`/`lng` 또는 `location` 열이 없으므로 지도 영역으로 필터링할 수 없습니다.',
  'rs.facets_help': '체크박스는 가장 자주 나오는 값을 보여 줍니다(제외를 쓰면 대신 걸러 냅니다). 범위와 시작/끝에는 숫자 또는 날짜 열이 필요합니다. 범위는 `from..to = label` 형식으로 `;`로 구분하고, 열린 끝은 비워 둡니다(`..1000`, `2020-01-01..`). 범위는 시작을 포함하고 끝은 포함하지 않습니다. 별점은 "별 4개 이상" 등을 제공합니다(최대 5, JSON의 `"max"`로 변경).',
  'rs.facets_help_chart': '차트: 패싯 아래에 개수를 보여 주는 막대 또는 원형 차트(접힘). 막대나 조각을 누르면 그 값으로 필터링합니다.',
  'rs.calendar_help': '쿼리는 `start_date`, `title`, 그리고 선택적으로 `end_date`를 반환합니다(종일 일정은 날짜, 시간이 있는 일정은 타임스탬프).',
  'rs.chart_help': '첫 번째 열은 레이블이고, 이어지는 숫자 열은 각각 계열입니다(최대 8개). 간트 차트는 `label, start, end`(날짜 또는 타임스탬프, 끝이 비어 있으면 마일스톤)와 선택 열 `progress`(0~100), `task_id`, `depends_on`(작업이 기다리는 id, 예: `3,4`)을 읽습니다.',
  'rs.map_help': '각 행은 `lat`, `lng`(또는 "lat,lng" 형식의 `location`) 위치의 마커이며, 팝업에 `title`과 `body`가 표시됩니다. `geojson` 열은 선과 영역을 그립니다(PostGIS가 설치되어 있으면 WGS 84의 `geometry` 또는 `geography` 열도 됩니다). 히트맵은 각 장소를 `weight` 열로 가중합니다.',
  'rs.tree_help': '쿼리는 `id`, `parent_id`, `label`(선택적으로 `icon`)을 반환합니다. 부모가 결과에 없는 행이 루트입니다.',
  'rs.workflow_help': '워크플로는 워크플로 정의(공유 구성요소)에서 나오며, 애플리케이션 SQL이 `meta.start_workflow(…)`로 시작합니다.',
  'rs.task_help': '작업은 작업 정의(공유 구성요소)에서 나오며, 애플리케이션 SQL이 `meta.create_task(…)`로 만듭니다.',
