  'rm.response_as': '{as}(으)로 {request}',
  'rm.try_intro': '실제 엔드포인트로 요청을 보냅니다: PUT, POST 또는 DELETE는 데이터를 변경합니다. {as}에서 계정을 고르면 앱 › REST API처럼 단기 토큰이 발급됩니다. 고르지 않으면 토큰 없는 호출자가 받는 결과를 볼 수 있습니다.',
  'rm.intro': 'RESTful 서비스 모듈: 모듈은 애플리케이션의 기본 경로이고, 템플릿은 `:parameters`가 있는 URI이며, 각 템플릿에는 메서드별 핸들러와 그 소스(컬렉션 쿼리, 단일 행, SQL, PL/pgSQL 블록 또는 미디어 리소스)가 있습니다. 핸들러는 애플리케이션의 데이터베이스 역할로 실행되고 호출자는 `meta.app_user()`이므로 그 권한과 행 수준 보안이 적용됩니다. 매개변수는 바인드되며 SQL에 붙여 넣어지지 않습니다. 모든 모듈에는 OpenAPI 문서가 있습니다. 모듈은 애플리케이션에 속하며 내보내기와 함께 이동합니다(공유 구성요소 › RESTful 서비스에도 있음).',
  'rm.source_help': '바인드 변수, 대문자: 경로 매개변수({params}), 쿼리 매개변수 및 JSON 본문 필드. `:BODY`는 본문 전체, `:APP_USER`는 호출자입니다. 값은 바인드되며 SQL에 붙여 넣어지지 않습니다. PL/pgSQL: `perform meta.rest_reply(jsonb_build_object(…), 201)`로 응답하는 블록(`declare … begin … end` 또는 문). 미디어: `content_type`, `content`, 선택적으로 `filename`을 반환하는 쿼리.',
  'rm.params_help': '한 줄에 하나: `name query|body|header [{types}] [required] [description]`. OpenAPI 문서와 사용해 보기 양식에 들어갑니다. 필수 항목이 없으면 400으로 응답합니다. header 매개변수는 이름의 _를 -로 바꾼 요청 헤더를 읽습니다(`x_request_id`는 `X-Request-Id`).',
  'rm.e.params_line': '매개변수, {n}행: "name query", "name body" 또는 "name header"를 쓰고, 선택적으로 유형({types}), "required", 설명을 쓰십시오.',
  'rm.e.choose_app': '이 작업 공간의 애플리케이션을 선택하십시오.',
  'rm.e.base_path': '기본 경로는 소문자로 시작합니다: 문자, 숫자, _ 및 -(최대 40자).',
