  'ar.intro': 'RESTful 서비스: 테이블이나 뷰를 REST 엔드포인트로 게시합니다(AutoREST). 행은 필터와 함께 JSON으로 페이지 단위로 반환되며, 기본 키가 있으면 단일 행 GET, PUT, DELETE를 쓸 수 있습니다. 요청은 게시한 애플리케이션의 데이터베이스 역할로 실행되고 호출자는 `meta.app_user()`이므로 그 권한과 행 수준 보안이 적용됩니다.',
