  'wres.servers_intro': '{workspace}의 이름 있는 기본 URL: REST 데이터 소스, REST 소스 카탈로그 또는 AI 서비스가 전체 URL 대신 서버와 경로를 지정하므로, 개발에서 운영으로 옮길 때 여기 값 하나(또는 환경 변수 하나)만 바꾸면 서버의 모든 소스가 즉시 따라갑니다. URL은 여전히 전체 URL의 모든 검사를 거칩니다: 설치의 허용 목록, 이 작업 공간의 {network} 목록, 호출 시 주소 검사.',
