  'wres.files_intro': '{workspace}의 모든 애플리케이션이 쓸 수 있는 CSS, JavaScript, JSON, 이미지, 글꼴: 애플리케이션은 공유 구성요소 → 정적 애플리케이션 파일 → 모든 페이지에서 로드에 {tag}을(를) 지정해 모든 페이지에서 로드하고(한 페이지만: 페이지 → 모양), 템플릿, HTML, 링크는 URL에 {sub}을(를) 씁니다. 각 애플리케이션은 자체 주소({path})에서 제공하며 다른 작업 공간의 파일은 제공하지 않습니다. 파일당 최대 {size}, HTML 불가. 작업 공간 내보내기와 함께 이동합니다.',
  'wres.type_help': 'basic: 사용자 이름 + 비밀번호 · header: 비밀 값이 든 HTTP 헤더(API 키) · bearer: Authorization: Bearer <secret> · oauth2: 클라이언트 자격 증명, 비밀번호 또는 새로 고침 토큰 부여 · aws_sigv4: S3 호환 객체 저장소.',
  'wres.credentials_intro': '{workspace}의 웹 자격 증명으로, 애플리케이션이 REST 데이터 소스, API 호출 프로세스, 원격 서버, 객체 저장소에서 이름으로 씁니다. 키는 작업 공간에서 한 번만 입력하면 됩니다. 같은 이름의 애플리케이션 자체 자격 증명(공유 구성요소 → 웹 자격 증명)이 우선합니다. 비밀 값은 서버 키로 암호화되며 다시 표시되거나 내보내지지 않습니다.',
