  'asst.who_the_assistant_is_and': '도우미가 누구이며 무엇에 답할 수 있는지. `&ITEM.`은(는) 항목 값으로 구분된 데이터로 대체됩니다(세션 ID나 비밀번호는 제외).',
  'asst.run_before_each_question_their': '각 질문 전에 실행되며 그 행이 데이터로 모델에 전달됩니다. `[{"name": "policy", "sql": "select title, body from hr.policy where body @@ plainto_tsquery(:AI_PROMPT)", "max_rows": 5}]`(`:AI_PROMPT`는 질문, `:APP_USER`와 항목은 평소처럼).',
  'asst.the_model_calls_them_when': '모델이 필요할 때 호출합니다. SQL: `{"name": "my_leave", "description": "…", "sql": "select … where status = :STATUS", "parameters": {"STATUS": {"type": "string", "enum": ["PENDING", "APPROVED"]}}}`. 데이터를 바꾸는 도구에는 `"writes": true`를, 일부 사용자에게만 제공하려면 `"authz": "SCHEME"`을 추가하십시오. REST: `{"name": "department", "type": "rest", "source": "DEPARTMENT", "description": "…", "parameters": {"dname": {"type": "string"}}}`. 매개변수 유형: string, integer, number, boolean, date. `"optional": true`이면 생략 가능.',
  'asst.agent_help': '{link}의 에이전트가 서비스, 시스템 프롬프트, 추론 강도, 도구, 단계를 설정합니다. 에이전트로 저장하면 영역 자체의 서비스, 시스템 프롬프트, 도구, 도구 라운드가 제거됩니다.',
  'asst.no_rest_source': '도구 "{tool}": REST 데이터 소스 {source}이(가) 없습니다.',
