  'asst.no_agent': 'AI 에이전트 {agent}이(가) 없습니다.',
  'asst.filter_intro': '사용자가 질문을 입력하면 보고서 자체 설정(필터, 강조, 정렬, 컨트롤 브레이크, 합계, 그룹화, 피벗, 차트, 계산 열. 보고서가 보여 주는 열과 연산자만)이 되어, 편집·제거·실행 취소할 수 있는 칩으로 표시됩니다. AI 서비스가 있으면 질문과 열 이름이 서비스 공급자로 보내지고, 없으면({builtin}) pgkiln이 영어, 네덜란드어, 독일어의 일반 문구를 직접 읽습니다.',
