  // ------------------------------------------------------------ JSON sources (sprint 164)
  'jsrc.a_column_per_path_in': '문서의 경로마다 열 하나(키는 점으로 구분, 예: `address.city`). 유형으로 읽을 수 없는 값은 비어 보입니다. 행을 저장하면 값이 바뀐 경로만 기록되며, 이 목록에 없는 키는 문서에 남습니다. 열을 제거하려면 이름을 비우십시오.',
