  'jsrc.json_sources': 'JSON 소스',
  'jsrc.a_json_source_describes_a': 'JSON 소스는 jsonb 열을 기술합니다: 문서의 경로마다 열 하나, 객체 배열은 각각의 행으로. pgkiln이 이를 바탕으로 갱신 가능한 뷰를 만들므로 양식, 보고서, 대화형 그리드, REST, MCP가 문서를 테이블처럼 읽고 씁니다. 행을 저장하면 바뀐 경로만 변경되며, 소스가 모르는 키는 남습니다. 테이블과 하위 테이블을 하나의 문서로 다루려면 SQL Workshop › 테이블 속성 › 문서 뷰를 보십시오.',
