  'agt.intro': '에이전트는 AI 도우미 영역에서 답하며, 준 도구로만 동작합니다: SQL 쿼리(읽기 전용, 애플리케이션 데이터베이스 역할로 실행하므로 행 수준 보안 적용), PL/pgSQL 함수, REST 데이터 소스, 브라우저의 JavaScript 작업, 페이지 링크(pgkiln이 URL과 체크섬을 만들며, 사용자가 열 수 있는 페이지만). Retrieve 도구는 검색 구성에서 텍스트와 의미가 맞는 행(RAG)을 에이전트에 제공합니다(역시 애플리케이션 역할로). 사용자가 입력한 내용과 도구 결과는 에이전트의 AI 서비스로 보내집니다. {usage}에 모든 도구 호출이 나열됩니다.',
