  'tel.send_traces_logs_and_metrics': 'OpenTelemetry Collector를 통해 애플리케이션의 추적, 로그, 메트릭을 자체 모니터링(Grafana, Jaeger, Datadog, Honeycomb, OCI APM 등 OTLP를 지원하는 모든 것)으로 보냅니다. 페이지 요청마다 추적 하나, SQL 문, REST 데이터 소스 호출, AI 요청, 도구 호출마다 span 하나씩이며, 메일과 워크플로 단계는 별도 추적입니다. pgkiln은 OTLP를 HTTP로 JSON 형식으로 보냅니다. 표준 `OTEL_*` 환경 변수도 작동하며, 여기서 설정한 값이 우선합니다. 안내서 1장(OpenTelemetry로 모니터링)에서 각 선택을 설명합니다.',
