  'dts.intro': '데이터 세트는 업무 사용자를 위한 {workspace} 데이터의 신뢰할 수 있는 뷰입니다. 한 스키마의 테이블과 뷰를 조인하고, 볼 수 있는 열, 레이블, 형식 마스크, 설명, 행 필터를 갖습니다. 하나 이상의 데이터 세트 위의 보고 애플리케이션에서는 사용자가 보고서를 만들고 저장하고 게시하고 공유할 수 있으며, 모든 보고서는 애플리케이션의 데이터베이스 역할로 실행되므로 권한과 행 수준 보안이 적용됩니다.',
