  'rcat.intro': '{workspace}용으로 한 번 기술한 웹 서비스: 기본 URL과 서비스. 애플리케이션은 공유 구성요소 → REST 데이터 소스 → 새로 만들기에서 서비스로 REST 데이터 소스를 만듭니다. 데이터 소스는 사본이며 자격 증명은 애플리케이션에 남습니다.',
