  'avl.intro': '실행 중인 애플리케이션을 사용할 수 있는 사람. 개발자는 같은 브라우저에서 빌더에 로그인한 사람입니다(개발자 도구 모음이 표시됨). 페이지, 파일 다운로드, REST 모듈 및 REST API는 이 설정을 따르며, 자동화, 워크플로, 백그라운드 작업 및 대기 중인 메일은 계속 실행됩니다. 이 설정은 이 설치에 속합니다. 내보내기에서는 제외되며 애플리케이션을 덮어쓰는 가져오기에서는 유지됩니다.',
